/* @lc app=leetcode id=3444 lang=kotlin */ class Solution { fun g(a: Long, b: Long): Long = if (b == 0L) a else g(b, a % b) fun minimumIncrements(nums: IntArray, target: IntArray): Int = target.size.let { t -> LongArray(1 shl t) { s -> (0 until t).filter { s shr it and 1 == 1 }.fold(1L) { l, i -> l / g(l, target[i].toLong()) * target[i] } }.let { lm -> nums.fold(LongArray(1 shl t) { if (it == 0) 0L else Long.MAX_VALUE / 4 }) { dp, x -> dp.copyOf().also { nd -> dp.indices.forEach { m -> (1 until (1 shl t)).forEach { sub -> nd[m or sub] = minOf(nd[m or sub], dp[m] + (lm[sub] - x % lm[sub]) % lm[sub]) } } } }.last().toInt() } } }